<script setup lang="ts">import{onMounted,ref}from'vue';import{getRanking,type RankRow}from'../services/ranking';import{useI18n}from'../i18n';const rows=ref<RankRow[]>([]),loading=ref(true),{t}=useI18n();onMounted(async()=>{rows.value=await getRanking();loading.value=false})</script><template><section class="screen sub"><RouterLink to="/home" class="back">← {{t('back')}}</RouterLink><h1>🏆 {{t('ranking')}}</h1><p v-if="loading">…</p><p v-else-if="!rows.length">{{t('noScores')}}</p><ol class="ranking"><li v-for="(r,i) in rows" :key="r.nickname"><b>{{r.position??i+1}}</b><span>{{r.nickname}}</span><strong>{{r.best_score}}</strong></li></ol></section></template>
